from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _dependencies(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    rows = {name: {row["version"]: row for row in choices}
            for name, choices in packages.items()}
    options = {}
    for name in packages:
        versions = [v for v in rows[name]
                    if v not in blocked.get(name, [])
                    and (name not in pins or pins[name] == v)]
        options[name] = [-1] + versions

    best_vector = None
    best = None
    for values in product(*(options[name] for name in packages)):
        chosen = dict(zip(packages, values))
        if any(chosen.get(name, -1) < bounds[0]
               or chosen.get(name, -1) > bounds[1]
               for name, bounds in data["roots"].items()):
            continue

        reachable = set()
        edges = {}
        pending = list(data["roots"])
        valid = True
        while pending and valid:
            name = pending.pop()
            if name in reachable:
                continue
            version = chosen.get(name, -1)
            if version < 0:
                valid = False
                break
            reachable.add(name)
            deps = [d for d in rows[name][version].get("deps", [])
                    if not d.get("feature") or d["feature"] in features]
            edges[name] = []
            for dep in deps:
                other = dep["name"]
                other_version = chosen.get(other, -1)
                if other_version < dep["min"] or other_version > dep["max"]:
                    valid = False
                    break
                edges[name].append(other)
                pending.append(other)
        if not valid or any(v >= 0 and name not in reachable
                            for name, v in chosen.items()):
            continue

        finished, active = set(), set()
        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            if any(not visit(other) for other in edges.get(name, [])):
                return False
            active.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in reachable):
            continue

        vector = tuple(chosen[name] for name in names)
        if (best_vector is None
                or (vector > best_vector if preference == "maximum"
                    else vector < best_vector)):
            best_vector = vector
            best = {name: chosen[name] for name in reachable}
    return {"versions": best} if best is not None else {"error": "unsatisfiable"}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        key = (event.get("revision", 0), pos)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(n, d):
        return n // d if mode == "floor" else (2 * n + d) // (2 * d)

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(net * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = {job["id"] for job in subset}
        if not mandatory <= ids or ids & blocked:
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        active_ends = []
        overlap = False
        for job in sorted(subset, key=lambda j: (j["start"], j["end"])):
            active_ends = [end for end in active_ends if end > job["start"]]
            if len(active_ends) >= 2:
                overlap = True
                break
            active_ends.append(job["end"])
        if overlap:
            continue
        selected = sorted(ids)
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_ids is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source = data["source"]
    initial_mask = bit.get(source, 0)
    start = data["start"]
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: start}
    queue = [(start, source, initial_mask, data["coupons"])]

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, left in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, left)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, left))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda d: _dependencies(d, "maximum", "ascending"),
    "component_02": lambda d: _dependencies(d, "minimum", "ascending"),
    "component_03": lambda d: _dependencies(d, "maximum", "descending"),
    "component_04": lambda d: _dependencies(d, "minimum", "descending"),
    "component_05": lambda d: _dependencies(d, "maximum", "ascending"),
    "component_06": _ledger,
    "component_07": _quota_intervals,
    "component_08": _routes,
}
